import java.io.*;
import java.util.*;
import java.text.*;
import java.lang.*;
import java.math.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter out = new PrintWriter(System.out);
    static final long MODULUS = (long) 1e9 + 7;
    static final long MODULUS1 = 998244353;

    public static void main(String[] args) throws Exception {
        long nCount = readLongInput();
        long mCount = readLongInput();
        long startL = readLongInput();
        long endR = readLongInput();

        long segmentLength = endR - startL + 1;
        long halfSegment = segmentLength / 2;
        long otherHalfSegment = segmentLength - halfSegment;
        long totalCells = nCount * mCount;

        long finalAnswer;
        if (totalCells % 2 == 1) {
            finalAnswer = segmentLength % MODULUS;
        } else {
            long sumOfSegments = (powerModulo(halfSegment + otherHalfSegment, totalCells, MODULUS) + powerModulo(Math.abs(halfSegment - otherHalfSegment), totalCells, MODULUS)) % MODULUS;
            finalAnswer = (sumOfSegments * modularInverse(2, MODULUS)) % MODULUS;
        }
        out.println(finalAnswer);
        out.flush();
        out.close();
    }

    static long readLongInput() throws IOException {
        String[] parts = br.readLine().split(" ");
        return Long.parseLong(parts[0]);
    }

    static long powerModulo(long base, long exp, long mod) {
        long result = 1;
        long baseMod = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * baseMod) % mod;
            baseMod = (baseMod * baseMod) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long modularInverse(long a, long m) {
        return powerModulo(a, m - 2, m);
    }
}
